include_once __DIR__.'/includes/session_check.php';require_login_modal();include __DIR__.'/db_connect.php';
$school=(int)($_SESSION['login_school_id']??0);$type=(int)($_SESSION['login_type']??0);if(!$school||$type!==1){echo '<div class="alert alert-danger">No tiene permisos para gestionar deudas.</div>';return;}if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));$csrf=$_SESSION['csrf_token'];
$ready=false;$q=$conn->query("SHOW COLUMNS FROM student_ef_list LIKE 'debt_status'");if($q&&$q->num_rows)$ready=true;$years=[];$active=0;$s=$conn->prepare('SELECT id,year,is_active,status FROM academic_year WHERE school_id=? ORDER BY year DESC');$s->bind_param('i',$school);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc()){$years[]=$x;if($x['is_active'])$active=(int)$x['id'];}$s->close();
$stats=['count'=>0,'assigned'=>0,'paid'=>0,'balance'=>0,'overdue'=>0];if($ready){$s=$conn->prepare("SELECT COUNT(*) count,COALESCE(SUM(COALESCE(ef.discounted_amount,ef.total_fee)),0) assigned,COALESCE(SUM((SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.ef_id=ef.id AND p.payment_status='Confirmado')),0) paid,COALESCE(SUM(CASE WHEN ef.due_date<CURDATE() AND ef.debt_status='Activa' AND (SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.ef_id=ef.id AND p.payment_status='Confirmado')<COALESCE(ef.discounted_amount,ef.total_fee) THEN 1 ELSE 0 END),0) overdue FROM student_ef_list ef INNER JOIN student st ON st.id=ef.student_id WHERE st.school_id=? AND ef.debt_status<>'Anulada'");$s->bind_param('i',$school);$s->execute();$stats=$s->get_result()->fetch_assoc();$s->close();$stats['balance']=(float)$stats['assigned']-(float)$stats['paid'];}
?>
