<script>(function($){const api='fees_api.php',csrf=<?php echo json_encode($csrf); ?>,ready=<?php echo $ready?'true':'false'; ?>;let selected={},table;function esc(v){return $('<div>').text(v==null?'':v).html()}function filters(){return{academic_year_id:$('#df-year').val(),level:$('#df-level').val(),payment_status:$('#df-payment').val(),debt_status:$('#df-status').val(),due_status:$('#df-due').val(),student_status:$('#df-student-status').val()}}function bulk(){let n=Object.keys(selected).length;$('#df-count').text(n);$('#df-bulk').toggleClass('show',n>0)}function initDebtTable(){if(!ready){$('#df-new,#df-bulk-new,#df-export').prop('disabled',true);return}if(!$.fn.DataTable){$('#df-table-error').removeClass('d-none').text('No se cargó el componente de tablas. Recargue la página.');return}if($.fn.DataTable.isDataTable('#feesTable'))$('#feesTable').DataTable().destroy();table=$('#feesTable').DataTable({serverSide:true,processing:true,pageLength:15,lengthMenu:[[15,25,50,100],[15,25,50,100]],order:[[2,'asc']],columnDefs:[{orderable:false,targets:[0,8]}],ajax:{url:'fees_table_data.php',type:'GET',data:function(d){return $.extend(d,filters())},dataSrc:function(json){$('#df-table-error').addClass('d-none').empty();if(json.migration_required)$('#df-table-error').removeClass('d-none').text(json.error||'La migración está pendiente.');return json.data||[]},error:function(xhr){let message='No se pudo cargar la tabla de deudas.';try{let response=JSON.parse(xhr.responseText);message=response.error||response.message||message}catch(e){if(xhr.responseText)message+=' '+xhr.responseText.substring(0,180)}$('#df-table-error').removeClass('d-none').text(message)}},language:{search:'Buscar:',lengthMenu:'Mostrar _MENU_',processing:'Cargando deudas...',zeroRecords:'No se encontraron deudas',info:'Mostrando _START_ a _END_ de _TOTAL_',infoEmpty:'Sin registros',paginate:{previous:'Anterior',next:'Siguiente'}}});table.on('draw',function(){$('.fee-checkbox').each(function(){this.checked=!!selected[this.value]});$('#df-all').prop('checked',false)})}$(initDebtTable);
$('#df-year,#df-level,#df-payment,#df-status,#df-due,#df-student-status').change(()=>table&&table.ajax.reload());$('#df-refresh').click(()=>table&&table.ajax.reload(null,false));$(document).on('change','.fee-checkbox',function(){this.checked?selected[this.value]=1:delete selected[this.value];bulk()});$('#df-all').change(function(){$('.fee-checkbox').each((_,x)=>{x.checked=this.checked;this.checked?selected[x.value]=1:delete selected[x.value]});bulk()});$('#df-clear').click(function(){selected={};bulk();table&&table.ajax.reload(null,false)});$('#df-operation').change(function(){$('#df-bulk-date').toggleClass('d-none',this.value!=='due_date');$('#df-reason').toggleClass('d-none',this.value!=='cancel')});function post(a,d){d.csrf_token=csrf;return $.post(api+'?action='+a,d,null,'json')}
$('#df-apply').click(function(){let ids=Object.keys(selected),op=$('#df-operation').val();if(!op)return alert_toast('Seleccione una acción.','warning');if(!confirm('¿Aplicar esta acción a '+ids.length+' deudas?'))return;post('bulk_action',{ids:JSON.stringify(ids),operation:op,due_date:$('#df-bulk-date').val(),reason:$('#df-reason').val()}).done(r=>{alert_toast(r.message,r.status==1?'success':'danger');if(r.status==1){selected={};bulk();table.ajax.reload(null,false)}}).fail(x=>alert_toast((x.responseJSON||{}).message||'No se pudo procesar.','danger'))});$('#df-new').click(()=>uni_modal('Asignar deuda individual','manage_fee.php','large'));$('#df-bulk-new').click(()=>uni_modal('Asignación masiva de deudas','bulk_assign_fees.php','large'));$(document).on('click','.edit_fees',function(){uni_modal('Editar deuda','manage_fee.php?id='+$(this).data('id'),'large')});$(document).on('click','.view_payment',function(){uni_modal('Información de pagos','view_payment.php?ef_id='+$(this).data('id')+'&pid=0','mid-large')});$(document).on('click','.delete-fee',function(){let id=$(this).data('id');if(!confirm('¿Eliminar esta asignación de deuda? Solo se eliminará si no tiene pagos, descuentos ni comprobantes.'))return;start_load();post('bulk_action',{ids:JSON.stringify([id]),operation:'delete'}).done(function(r){alert_toast(r.message,r.processed==1?'success':'warning');if(r.processed==1)table.ajax.reload(null,false)}).fail(x=>alert_toast((x.responseJSON||{}).message||'No se pudo eliminar la deuda.','danger')).always(function(){end_load()})});window.reload_table=()=>{if(table)table.ajax.reload(null,false)};
$('#df-export').click(function(){let p=filters();p.ids=Object.keys(selected).join(',');location='export_fees.php?'+$.param(p)});$('#df-audit').click(function(){$('#debtAudit').modal('show');$('#df-audit-body').html('<tr><td colspan="6" class="text-center"><i class="fa fa-spinner fa-spin"></i></td></tr>');$.getJSON(api,{action:'audit',academic_year_id:$('#df-year').val()}).done(r=>{let h='';(r.audit||[]).forEach(x=>h+='<tr><td>'+esc(x.created_at)+'</td><td>'+esc(x.user_name)+'</td><td>'+esc(x.student_name)+'</td><td>'+esc(x.concept_name)+'</td><td>'+esc(x.action)+'</td><td><small>'+esc(x.details||'')+'</small></td></tr>');$('#df-audit-body').html(h||'<tr><td colspan="6" class="text-center text-muted">Sin movimientos.</td></tr>')})});})(jQuery);</script>
